import{_ as c,C as i,o as n,c as l,aj as a,E as o,j as t,a as r}from"./chunks/framework.DkvuVDKz.js";const z=JSON.parse('{"title":"Resizable 可调容器","description":"","frontmatter":{},"headers":[],"relativePath":"components/resizable.md","filePath":"components/resizable.md","lastUpdated":1789272501000}'),s={name:"components/resizable.md"};function h(b,e,u,p,m,g){const d=i("XhDemo");return n(),l("div",null,[e[0]||(e[0]=a('<h1 id="resizable-可调容器" tabindex="-1">Resizable 可调容器 <a class="header-anchor" href="#resizable-可调容器" aria-label="Permalink to &quot;Resizable 可调容器&quot;">​</a></h1><p>通过拖拽或键盘调整内容区域的尺寸。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/resizable" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/resizable.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/resizable" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/resizable" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/resizable.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>从右侧、底部或右下角调整尺寸</p>',5)),o(d,{src:"resizable/01-basic"}),e[1]||(e[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;resizable&quot;</code>：<strong><code>root</code></strong> · <code>handle</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="全部边缘" tabindex="-1">全部边缘 <a class="header-anchor" href="#全部边缘" aria-label="Permalink to &quot;全部边缘&quot;">​</a></h3><p>从任意边缘或角点调整尺寸</p>',6)),o(d,{src:"resizable/02-edges"}),e[2]||(e[2]=t("h3",{id:"约束",tabindex:"-1"},[r("约束 "),t("a",{class:"header-anchor",href:"#约束","aria-label":'Permalink to "约束"'},"​")],-1)),e[3]||(e[3]=t("p",null,"设置宽高比和步进",-1)),o(d,{src:"resizable/03-constraints"}),e[4]||(e[4]=t("h3",{id:"禁用",tabindex:"-1"},[r("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),e[5]||(e[5]=t("p",null,"禁止调整尺寸",-1)),o(d,{src:"resizable/04-disabled"}),e[6]||(e[6]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>调整侧栏、卡片或编辑器预览区域。</li><li>保存用户设置的内容尺寸。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>两块区域联动调整时使用<a href="./splitter">分栏</a>。</li><li>表格列宽使用<a href="./table">表格</a>内置调整。</li><li>可拖动浮窗使用<a href="./floating-panel">浮动面板</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持八个方向的调整把手。</li><li>支持最小/最大尺寸、宽高比和步进约束。</li><li>支持方向键、Home、End 和 Escape。</li><li>调整中和调整结束分别提供回调。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>可在内部放置<a href="./scroll-area">滚动区域</a>。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-resizable&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhResizableHandle</code> <code>XhResizableRoot</code></td></tr><tr><td>组合式函数</td><td><code>useResizable</code></td></tr><tr><td>状态机</td><td><code>resizableMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/resizable.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>dimensions</code></td><td><code>ResizableDimensions</code></td><td></td><td>受控尺寸。给了就由外面说了算，内部只发意图。</td></tr><tr><td><code>defaultDimensions</code></td><td><code>ResizableDimensions</code></td><td></td><td></td></tr><tr><td><code>minWidth</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>minHeight</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>maxWidth</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>maxHeight</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>aspectRatio</code></td><td><code>number</code></td><td></td><td>宽高比（宽 ÷ 高）。给了就锁死；四条边各按自己那一轴算另一轴，四个角以宽为准。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>吸附步进：宽高各自落到最近的整数倍。</td></tr><tr><td><code>keyboardStep</code></td><td><code>number</code></td><td></td><td>方向键一次推多远（px），默认 8。</td></tr><tr><td><code>keyboardLargeStep</code></td><td><code>number</code></td><td></td><td>按住 Shift 时的步长（px），默认 40。</td></tr><tr><td><code>edges</code></td><td><code>ResizeEdge[]</code></td><td></td><td>允许哪几条边可调，默认八向全开。 只给东南两向就是「只能往右下角撑大」，那是文档流里最常见的形态。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ResizableTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onDimensionsChange</code></td><td><code>(details: ResizableDimensionsChangeDetails) =&gt; void</code></td><td></td><td>尺寸变化意图。拖动途中连着发。</td></tr><tr><td><code>onDimensionsChangeEnd</code></td><td><code>(details: ResizableDimensionsChangeEndDetails) =&gt; void</code></td><td></td><td>一次调整收尾发一次。存尺寸用它，别用 onDimensionsChange。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>dimensions-change</code></td><td><code>ResizableDimensionsChangeDetails</code></td><td>尺寸变化（拖动途中会连发）；detail 为 <code>{ dimensions }</code></td></tr><tr><td><code>dimensions-change-end</code></td><td><code>ResizableDimensionsChangeEndDetails</code></td><td>一次调整收尾发一次；detail 为 <code>{ dimensions, edge }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhResizableHandle</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhResizableRoot</code></td><td><code>default</code></td><td><code>ResizableRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>resizing</code></p><p><strong>事件</strong>：<code>RESIZE.START</code> · <code>RESIZE.MOVE</code> · <code>RESIZE.END</code> · <code>RESIZE.CANCEL</code> · <code>RESIZE.NUDGE</code> · <code>RESIZE.TO_BOUND</code> · <code>DIMENSIONS.SET</code></p><p><strong>判据</strong>：<code>canResize</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>dimensions</code></td><td><code>ResizableDimensions</code></td><td></td></tr><tr><td><code>offset</code></td><td><code>ResizableOffset</code></td><td></td></tr><tr><td><code>resizing</code></td><td><code>boolean</code></td><td>正在调整（拖动中）。键盘推一步不算。</td></tr><tr><td><code>activeEdge</code></td><td><code>ResizeEdge | null</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>edgeEnabled</code></td><td><code>(edge: ResizeEdge) =&gt; boolean</code></td><td>这条边是否开放。</td></tr><tr><td><code>setDimensions</code></td><td><code>(dimensions: ResizableDimensions) =&gt; void</code></td><td>整份赋值：先过约束再落地。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHandleProps</code></td><td><code>(props: { edge: ResizeEdge }) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/windowsplitter/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in handle, not disabled</td><td>按屏幕方向推这条边一步（默认 8px）——推东边是变宽、推西边是变窄，与拖动同义。按的是屏幕方向，rtl 下两键不对调——那时改由「行尾侧」这条边落在屏幕左边来体现</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in handle, not disabled</td><td>往反方向推一步，规则同上</td></tr><tr><td><code>Shift+ArrowRight</code> / <code>Shift+ArrowLeft</code> / <code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code></td><td>focus in handle, not disabled</td><td>按大步长推（默认 40px）</td></tr><tr><td><code>Home</code></td><td>focus in handle, not disabled</td><td>把这条边推到它眼下能到的最小尺寸</td></tr><tr><td><code>End</code></td><td>focus in handle, not disabled</td><td>推到最大尺寸；没给上限时不动</td></tr><tr><td><code>Escape</code></td><td>调整中</td><td>放弃这一次调整，尺寸与位移退回按下那一刻；收尾回调不发</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>translations?.root</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-label</code></td><td>translations?.handle?.(edge)</td></tr><tr><td><code>handle</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-valuenow</code></td><td>Math.round(edge === &#39;n&#39; || edge === &#39;s&#39; ? dimensions.…</td></tr><tr><td><code>handle</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/resizable.css</code> 使用 <code>[data-scope=&quot;resizable&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-edge</code></td><td>context.get(&#39;activeEdge&#39;)</td></tr><tr><td><code>root</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>handle</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>handle</code></td><td><code>data-edge</code></td><td>edge</td></tr><tr><td><code>handle</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-resizable-corner</code></td><td><code>handle</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>inset-block-end</code><br><code>inset-block-start</code><br><code>inset-inline-end</code><br><code>inset-inline-start</code></td><td><code>edge=ne</code><br><code>edge=nw</code><br><code>edge=se</code><br><code>edge=sw</code></td><td><code>--xh-space-3</code></td><td>resizable 的 handle 部件 block-size、inline-size、inset-block-end、inset-block-start、inset-inline-end、inset-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-resizable-grip</code></td><td><code>handle</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>inset-block</code><br><code>inset-block-end</code><br><code>inset-block-start</code><br><code>inset-inline</code><br><code>inset-inline-end</code><br><code>inset-inline-start</code></td><td><code>edge=e</code><br><code>edge=n</code><br><code>edge=s</code><br><code>edge=w</code></td><td><code>--xh-space-2</code></td><td>resizable 的 handle 部件 block-size、inline-size、inset-block、inset-block-end、inset-block-start、inset-inline、inset-inline-end、inset-inline-start 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>边缘使用逻辑方向，自动适配 RTL。</li><li>键盘方向始终对应屏幕方向。</li></ul>',51))])}const k=c(s,[["render",h]]);export{z as __pageData,k as default};
